namespace hanmo::resident {namespace {
bool identity(const WorldIdentity& a,const WorldIdentity& b){return std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)==std::tie(b.world_id,b.execution_epoch,b.revision,b.tick);}
bool context(const InteractionContext& a,const InteractionContext& b){return std::tie(a.place_id,a.role_id,a.provider_actor_id,a.kind,a.encounter_id,a.input_error)==std::tie(b.place_id,b.role_id,b.provider_actor_id,b.kind,b.encounter_id,b.input_error);}
const DialogueDefinition* dialogue(const InteractionCatalog& c,const StableId& id){for(const auto& d:c.dialogues)if(d.id==id)return &d;return nullptr;}
const DialogueNode* node(const DialogueDefinition& d,const StableId& id){for(const auto& n:d.nodes)if(n.id==id)return &n;return nullptr;}
bool actual_start(const CommonStore& c,const StableId& id){const StableId prefix="tactic_lesson:";if(id.rfind(prefix,0)!=0)return false;Integer n=0;const auto digits=id.substr(prefix.size());const auto parsed=std::from_chars(digits.data(),digits.data()+digits.size(),n);const auto* h=c.state().facts.find(id);return parsed.ec==std::errc{}&&parsed.ptr==digits.data()+digits.size()&&n>0&&n<c.state().next_instance_id&&std::to_string(n)==digits&&h&&h->id==id&&h->kind=="tactic_lesson_started"&&h->domain=="growth_tactic_lessons";}
StableId kind(MilitaryTacticLearningSourceKind value){switch(value){case MilitaryTacticLearningSourceKind::authored_initial:return "authored_initial";case MilitaryTacticLearningSourceKind::teaching:return "teaching";case MilitaryTacticLearningSourceKind::practice:return "practice";}return {};}
GrowthTacticTeacherSource freeze(const MilitaryTacticLearningObservation& p){return {kind(p.source_kind),p.acquisition_fact_id,p.source_fact_id,p.initial_grant_id,p.acquired_tick,{}};}
bool teacher_equal(const GrowthTacticTeacherSource& a,const GrowthTacticTeacherSource& b){return std::tie(a.source_kind,a.acquisition_fact_id,a.source_fact_id,a.initial_grant_id,a.acquired_tick)==std::tie(b.source_kind,b.acquisition_fact_id,b.source_fact_id,b.initial_grant_id,b.acquired_tick);}
bool prerequisite_equal(const GrowthTacticPrerequisite& a,const GrowthTacticPrerequisite& b){return std::tie(a.skill_id,a.origin_kind,a.initial_prototype_id,a.required_level,a.observed_tick,a.initial_created_tick,a.initial_xp,a.minimum_xp,a.minimum_level,a.initial_source_ids,a.study_source_ids)==std::tie(b.skill_id,b.origin_kind,b.initial_prototype_id,b.required_level,b.observed_tick,b.initial_created_tick,b.initial_xp,b.minimum_xp,b.minimum_level,b.initial_source_ids,b.study_source_ids);}
// 目录授权的是原教师本人发言，不接受听者台词或choice/action冒提供者愿意授课。
Status declaration(const InteractionCatalog& talks,const GrowthTacticLessonDefinition& d){
    if(!talks.common)return common_failure("TacticLessonCommonCatalogRequired");const auto* talk=dialogue(talks,d.dialogue_id);const auto* saying=talk?node(*talk,d.offer_node_id):nullptr;const auto* role=talk?talks.common->roles.find(talk->context_role):nullptr;
    if(!talk||!saying||!role||role->initial_actor!=d.teacher_actor_id||role->organization_id||saying->kind!="say"||(saying->speaker!="$provider"&&saying->speaker!=d.teacher_actor_id))return common_failure("TacticLessonTeacherSayRequired",d.id);
    const auto* wallet=talks.common->required_wallets.find(d.recipient_wallet_id);if(!wallet||!owner_equal(wallet->owner,Owner{Owner::Kind::actor,d.teacher_actor_id,{},{}}))return common_failure("TacticLessonPrivateTeacherAccountRequired",d.id);return common_success();
}
Outcome<MilitaryTacticTeachingTarget> target(const CommonStore& c,const GrowthTacticLessonDefinition& d,const MilitaryTacticKnowledgeRead& read){
    auto t=read.tactic_definition(d.tactic_id);if(!t.ok)return t;if(!identity(t.value.source_identity,c.state().identity)||t.value.tactic_id!=d.tactic_id||std::find(t.value.teacher_actor_ids.begin(),t.value.teacher_actor_ids.end(),d.teacher_actor_id)==t.value.teacher_actor_ids.end())return {false,{},common_failure("TacticLessonTeacherNotListed",d.id).error};return t;
}
// 热/冷均调用同一军事原掌握纯读；未来学生取得不参与教师的过去资格。
Outcome<GrowthTacticTeacherSource> teacher_source(const CommonStore& c,const GrowthTacticLessonDefinition& d,const MilitaryTacticKnowledgeRead& read,Integer tick,const StableId& before){
    auto p=before.empty()?read.current_tactic(d.teacher_actor_id,d.tactic_id):read.tactic_before(d.teacher_actor_id,d.tactic_id,tick,before);if(!p.ok)return {false,{},p.error};
    if(!p.value||!identity(p.value->source_identity,c.state().identity)||p.value->actor_id!=d.teacher_actor_id||p.value->tactic_id!=d.tactic_id||p.value->observed_tick!=tick||p.value->before_fact_id!=before||p.value->acquired_tick<0||p.value->acquired_tick>tick||p.value->acquisition_fact_id.empty())return {false,{},common_failure("TacticLessonTeacherKnowledgeRequired",d.id).error};return {true,freeze(*p.value),{}};
}
Status source_binding(const CommonStore& c,const InteractionCatalog& talks,const GrowthTacticLessonCatalog& catalog,const GrowthTacticLessonSourceAccess& access,const GrowthTacticLessonAgreement& s,const StableId& before){
    if(talks.common.get()!=&access.origins.common||!access.person_before||!access.player_before)return common_failure("TacticLessonSourceAccessRequired");const auto* d=catalog.definitions.find(s.definition_id);if(!d)return common_failure("TacticLessonDefinitionMissing");auto checked=validate_growth_tactic_lesson_definition_shape(*d);if(!checked.ok)return checked;checked=declaration(talks,*d);if(!checked.ok)return checked;
    const auto* talk=dialogue(talks,d->dialogue_id);const auto* role=talks.common->roles.find(talk->context_role);
    if(s.world_id!=c.state().identity.world_id||s.scenario_id!=c.state().metadata.scenario_id||s.teacher_id!=d->teacher_actor_id||s.student_id.empty()||s.teacher_id==s.student_id||s.tactic_id!=d->tactic_id||s.dialogue_id!=d->dialogue_id||s.node_id!=d->offer_node_id||s.duration!=d->duration||s.total_fee!=d->total_fee||s.recipient_wallet_id!=d->recipient_wallet_id||s.payer_wallet_id.empty()||s.payer_wallet_id==s.recipient_wallet_id||s.session_id.empty()||s.session_id.size()>256||s.tick<0||s.tick>c.tick()||s.revision<0||s.revision>c.revision()||!face_to_face_contact_context_valid(s.context)||s.context.kind||s.context.encounter_id||s.context.input_error||s.context.provider_actor_id!=s.teacher_id||s.context.role_id!=talk->context_role||s.context.place_id!=role->place_id||s.place_id!=role->place_id)return common_failure("TacticLessonAgreementMismatch");
    auto who=access.player_before(s.tick,before);if(!who.ok)return {false,{},who.error};if(who.value!=s.student_id)return common_failure("TacticLessonStudentDecisionRequired");for(const auto* person:{&s.student_id,&s.teacher_id}){checked=access.person_before(*person,s.tick,before);if(!checked.ok)return checked;}
    auto t=target(c,*d,access.military);if(!t.ok)return {false,{},t.error};auto qualified=before.empty()?read_growth_tactic_lesson_qualification(c,access.origins,access.growth,s.student_id,t.value.prerequisite_skill_id):read_growth_tactic_lesson_qualification_before_start(c,access.origins,access.growth,s.student_id,t.value.prerequisite_skill_id,s.tick,before);if(!qualified.ok)return {false,{},qualified.error};auto q=freeze_growth_tactic_lesson_prerequisite(qualified.value,t.value.prerequisite_level);checked=validate_growth_tactic_lesson_prerequisite_shape(q);if(!checked.ok)return checked;if(!prerequisite_equal(q,s.prerequisite))return common_failure("TacticLessonQualificationChanged");
    auto teacher=teacher_source(c,*d,access.military,s.tick,before);if(!teacher.ok)return {false,{},teacher.error};if(!teacher_equal(teacher.value,s.teacher_source))return common_failure("TacticLessonTeacherSourceChanged");auto student=before.empty()?access.military.current_tactic(s.student_id,s.tactic_id):access.military.tactic_before(s.student_id,s.tactic_id,s.tick,before);if(!student.ok)return {false,{},student.error};if(student.value)return common_failure("TacticLessonAlreadyLearned");return common_success();
}
}
Status validate_growth_tactic_lesson_catalog(const CommonStore& c,const InteractionCatalog& talks,const GrowthTacticLessonCatalog& catalog,const MilitaryTacticKnowledgeRead& military){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 46, "GrowthTacticLessonCatalog", "validate_growth_tactic_lesson_catalog", &catalog);

    if(!talks.common||catalog.definitions.empty()||catalog.definitions.size()>4096)return common_failure("InvalidTacticLessonCatalog");std::set<std::tuple<StableId,StableId,StableId>> seen;
    for(const auto& row:catalog.definitions.rows()){const auto& d=row.second;auto checked=validate_growth_tactic_lesson_definition_shape(d);if(!checked.ok)return checked;if(row.first!=d.id||std::find(talks.common->actor_ids.begin(),talks.common->actor_ids.end(),d.teacher_actor_id)==talks.common->actor_ids.end())return common_failure("UnknownTacticLessonTeacher",row.first);checked=declaration(talks,d);if(!checked.ok)return checked;if(!seen.emplace(d.teacher_actor_id,d.dialogue_id,d.offer_node_id).second)return common_failure("AmbiguousTacticLessonOffer",row.first);auto t=target(c,d,military);if(!t.ok)return {false,{},t.error};}return common_success();
}
bool growth_tactic_lesson_agreement_equal(const GrowthTacticLessonAgreement& a,const GrowthTacticLessonAgreement& b){return std::tie(a.definition_id,a.tactic_id,a.student_id,a.teacher_id,a.place_id,a.payer_wallet_id,a.recipient_wallet_id,a.dialogue_id,a.node_id,a.session_id,a.scenario_id,a.world_id,a.tick,a.revision,a.duration,a.total_fee)==std::tie(b.definition_id,b.tactic_id,b.student_id,b.teacher_id,b.place_id,b.payer_wallet_id,b.recipient_wallet_id,b.dialogue_id,b.node_id,b.session_id,b.scenario_id,b.world_id,b.tick,b.revision,b.duration,b.total_fee)&&context(a.context,b.context)&&teacher_equal(a.teacher_source,b.teacher_source)&&prerequisite_equal(a.prerequisite,b.prerequisite);}
Outcome<GrowthTacticLessonQuote> preview_growth_tactic_lesson(const CommonStore& c,const InteractionState& meetings,const InteractionCatalog& talks,const InteractionAccess& interaction,const GrowthTacticLessonCatalog& catalog,const GrowthTacticLessonSourceAccess& access,const StableId& student,const StableId& definition){
    auto checked=validate_growth_tactic_lesson_catalog(c,talks,catalog,access.military);if(!checked.ok)return {false,{},checked.error};const auto* d=catalog.definitions.find(definition);const auto* actor=c.actor(student);if(!d||!actor||student!=c.state().metadata.player_actor_id||student==d->teacher_actor_id)return {false,{},common_failure("TacticLessonStudentDecisionRequired").error};
    for(const auto* id:{&student,&d->teacher_actor_id}){const auto* person=c.actor(*id);if(!person||!person->alive||!person->available||!person->action_id.empty())return {false,{},common_failure("TacticLessonParticipantUnavailable",*id).error};}
    auto proof=preview_authored_provider_source(c,meetings,talks,interaction,student,d->teacher_actor_id);if(!proof.ok)return {false,{},proof.error};const auto& p=proof.value.meeting;if(p.dialogue_id!=d->dialogue_id||p.node_id!=d->offer_node_id)return {false,{},common_failure("TacticLessonOfferNotCurrent").error};
    for(const auto& other:meetings.interactions)if(other.id!=p.session_id&&(other.actor_id==student||other.actor_id==d->teacher_actor_id||other.context.provider_actor_id==student||other.context.provider_actor_id==d->teacher_actor_id))return {false,{},common_failure("TacticLessonParticipantInOtherMeeting").error};
    auto t=target(c,*d,access.military);if(!t.ok)return {false,{},t.error};auto q=read_growth_tactic_lesson_qualification(c,access.origins,access.growth,student,t.value.prerequisite_skill_id);if(!q.ok)return {false,{},q.error};auto teacher=teacher_source(c,*d,access.military,c.tick(),{});if(!teacher.ok)return {false,{},teacher.error};
    GrowthTacticLessonAgreement s;s.definition_id=d->id;s.tactic_id=d->tactic_id;s.student_id=student;s.teacher_id=d->teacher_actor_id;s.place_id=p.context.place_id;s.payer_wallet_id=actor->wallet_id;s.recipient_wallet_id=d->recipient_wallet_id;s.dialogue_id=p.dialogue_id;s.node_id=p.node_id;s.session_id=p.session_id;s.scenario_id=c.state().metadata.scenario_id;s.world_id=c.state().identity.world_id;s.context=p.context;s.tick=c.tick();s.revision=c.revision();s.duration=d->duration;s.total_fee=d->total_fee;s.teacher_source=teacher.value;s.prerequisite=freeze_growth_tactic_lesson_prerequisite(q.value,t.value.prerequisite_level);checked=source_binding(c,talks,catalog,access,s,{});if(!checked.ok)return {false,{},checked.error};
    const auto* payer=c.wallet(s.payer_wallet_id);const auto* payee=c.wallet(s.recipient_wallet_id);if(!payer||!payee||!owner_equal(payer->owner,Owner{Owner::Kind::actor,student,{},{}})||!owner_equal(payee->owner,Owner{Owner::Kind::actor,s.teacher_id,{},{}}))return {false,{},common_failure("TacticLessonPrivatePaymentRequired").error};auto spendable=c.spendable(s.payer_wallet_id);if(!spendable.ok)return {false,{},spendable.error};if(spendable.value<s.total_fee)return {false,{},common_failure("InsufficientFunds").error};return {true,{proof.value,std::move(s)},{}};
}
Status revalidate_growth_tactic_lesson(const CommonStore& c,const InteractionState& meetings,const InteractionCatalog& talks,const InteractionAccess& interaction,const GrowthTacticLessonCatalog& catalog,const GrowthTacticLessonSourceAccess& access,const GrowthTacticLessonQuote& quote){
    auto checked=revalidate_authored_provider_source(c,meetings,talks,interaction,quote.teacher_say);if(!checked.ok)return checked;auto fresh=preview_growth_tactic_lesson(c,meetings,talks,interaction,catalog,access,quote.agreement.student_id,quote.agreement.definition_id);if(!fresh.ok)return {false,{},fresh.error};
    const auto& a=quote.teacher_say.meeting;const auto& b=fresh.value.teacher_say.meeting;if(!identity(a.source_identity,b.source_identity)||a.actor_id!=b.actor_id||a.provider_actor_id!=b.provider_actor_id||a.session_id!=b.session_id||a.dialogue_id!=b.dialogue_id||a.node_id!=b.node_id||a.node_kind!=b.node_kind||!context(a.context,b.context)||quote.teacher_say.speaker_actor_id!=fresh.value.teacher_say.speaker_actor_id||!growth_tactic_lesson_agreement_equal(quote.agreement,fresh.value.agreement))return common_failure("StaleTacticLessonQuote");return common_success();
}
Status validate_growth_tactic_lesson_agreement_before_start(const CommonStore& c,const InteractionCatalog& talks,const GrowthTacticLessonCatalog& catalog,const GrowthTacticLessonSourceAccess& access,const GrowthTacticLessonAgreement& source,const StableId& before){if(!actual_start(c,before))return common_failure("TacticLessonStartBoundaryRequired");return source_binding(c,talks,catalog,access,source,before);}
}
